    /// This binds directly as raw bytes and works with sqlite-vec APIs that accept
    /// float vectors (the default subtype).
    #[derive(Clone, Debug, PartialEq)]
    pub struct VecF32(pub Vec<f32>);

    /// An `int8` vector stored as a BLOB.
    ///
    /// sqlite-vec requires an explicit SQL wrapper to set the subtype for int8
    /// vectors. Use `vec_int8(?)` around bound parameters.
    #[derive(Clone, Debug, Eq, PartialEq)]
    pub struct VecInt8(pub Vec<i8>);

    /// Result of a WAL checkpoint operation.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub struct WalCheckpoint {
        /// Total frames in the WAL, or `None` when SQLite reports `-1`.
        pub log_frames: Option<i32>,
        /// Frames checkpointed from the WAL, or `None` when SQLite reports `-1`.
        pub checkpointed_frames: Option<i32>,
    }

    #[non_exhaustive]
    /// WAL checkpoint mode.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum WalCheckpointMode {
        /// Return WAL status without checkpointing frames.
        Noop,
        /// Checkpoint without waiting for readers or writers.
        Passive,
        /// Wait for writers, then checkpoint all frames possible without blocking
        /// readers.
        Full,
        /// Like full checkpointing, and reset the WAL if all frames are
        /// checkpointed.
        Restart,
        /// Like restart checkpointing, and truncate the WAL to zero bytes on
        /// success.
        Truncate,
    }

    pub use musq_macros::*;
    /// Helper trait used internally to determine if all columns belonging to a
    /// record are `NULL` in a given row.
    pub trait AllNull<'r> {
        /// Returns `true` if all columns for this type are `NULL`.
        fn all_null(prefix: &str, row: &'r Row) -> Result<bool>;
    }

    /// A type that may be executed against a database connection.
    ///
    /// This trait is **sealed** and cannot be implemented outside of this crate.
    ///
    /// Implemented for the following:
    ///
    ///  * [`Query`](super::query::Query)
    ///  * [`Map<F>`](super::query::Map)
    pub trait Execute: Send + Sized + sealed::Sealed {
        /// Returns the arguments to be bound against the query string.
        ///
        /// Returning `None` for `Arguments` indicates to use a "simple" query
        /// protocol and to not prepare the query. Returning
        /// `Some(Default::default())` is an empty arguments object that will be
        /// prepared (and cached) before execution.
        fn arguments(&mut self) -> Option<Arguments>;

        /// Gets the SQL that will be executed.
        fn sql(&self) -> &str;
    }

    /// A record that can be built from a row returned by the database.
    ///
    /// To use [`query_as`](crate::query_as) the output type must implement
    /// `FromRow`.
    ///
    /// ## Derivable
    ///
    /// This trait can be derived for structs. The generated implementation will
    /// make a sequence of calls to [`Row::get_value`] using the name from each
    /// struct field.
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// struct User {
    ///     id: i32,
    ///     name: String,
    /// }
    /// ```
    ///
    /// ### Field attributes
    ///
    /// Several attributes can be specified to customize how each column in a row is
    /// read:
    ///
    /// #### `rename`
    ///
    /// When the name of a field in Rust does not match the name of its
    /// corresponding column, you can use the `rename` attribute to specify the name
    /// that the field has in the row. For example:
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// struct User {
    ///     id: i32,
    ///     name: String,
    ///     #[musq(rename = "description")]
    ///     about_me: String
    /// }
    /// ```
    ///
    /// Given a query such as:
    ///
    /// ```sql
    /// SELECT id, name, description FROM users;
    /// ```
    ///
    /// will read the content of the column `description` into the field `about_me`.
    ///
    /// #### `rename_all`
    ///
    /// By default, field names are expected verbatim (with the exception of the raw
    /// identifier prefix `r#`, if present). Placed at the struct level, this
    /// attribute changes how the field name is mapped to its SQL column name:
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// #[musq(rename_all = "camel_case")]
    /// struct UserPost {
    ///     id: i32,
    ///     // remapped to "userId"
    ///     user_id: i32,
    ///     contents: String
    /// }
    /// ```
    ///
    /// An explicit `rename` on a field always wins over `rename_all`.
    ///
    /// The supported values are `snake_case`, `lower_case`, `upper_case`,
    /// `screaming_snake_case`, `kebab_case`, `camel_case`, `pascal_case`, and
    /// `verbatim`.
    ///
    /// #### `default`
    ///
    /// When your struct contains a field that is not present in your query, if the
    /// field type has an implementation for [`Default`], you can use the `default`
    /// attribute to assign the default value to said field. For example:
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// struct User {
    ///     id: i32,
    ///     name: String,
    ///     #[musq(default)]
    ///     location: Option<String>
    /// }
    /// ```
    ///
    /// Given a query such as:
    ///
    /// ```sql
    /// SELECT id, name FROM users;
    /// ```
    ///
    /// will set the value of the field `location` to the default value of
    /// `Option<String>`, which is `None`.
    ///
    /// ### `flatten`
    ///
    /// If you want to handle a field that implements [`FromRow`], you can use the
    /// `flatten` attribute to specify that you want it to use [`FromRow`] for
    /// parsing rather than the usual method. For example:
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// struct Address {
    ///     country: String,
    ///     city: String,
    ///     road: String,
    /// }
    ///
    /// #[derive(FromRow)]
    /// struct User {
    ///     id: i32,
    ///     name: String,
    ///     #[musq(flatten)]
    ///     address: Address,
    /// }
    /// ```
    /// Given a query such as:
    ///
    /// ```sql
    /// SELECT id, name, country, city, road FROM users;
    /// ```
    ///
    /// This field is compatible with the `default` attribute.
    ///
    /// #### `skip`
    ///
    /// This is a variant of the `default` attribute which instead always takes the
    /// value from the `Default` implementation for this field type ignoring any
    /// results in your query. This can be useful if some field does not satisfy
    /// the `Decode` bounds, in particular in the case of nested structures. For
    /// example:
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// struct Address {
    ///     user_name: String,
    ///     street: String,
    ///     city: String,
    /// }
    ///
    /// #[derive(FromRow)]
    /// struct User {
    ///     name: String,
    ///     #[musq(skip)]
    ///     addresses: Vec<Address>,
    /// }
    /// ```
    ///
    /// Then when querying into `User`, only `name` needs to be set:
    ///
    /// ```rust,ignore
    /// let user: User = query_as("SELECT name FROM users")
    ///    .fetch_one(&mut some_connection)
    ///    .await?;
    /// assert!(user.addresses.is_empty());
    /// ```
    ///
    /// `Default` for `Vec<Address>` is an empty vector.
    ///
    /// ## Manual implementation
    ///
    /// You can also implement the [`FromRow`] trait by hand. This can be useful if
    /// you have a struct with a field that needs manual decoding:
    ///
    ///
    /// ```rust,ignore
    /// use musq::{FromRow, Result, Row};
    /// struct MyCustomType {
    ///     custom: String,
    /// }
    ///
    /// struct Foo {
    ///     bar: MyCustomType,
    /// }
    ///
    /// impl FromRow<'_> for Foo {
    ///     fn from_row(prefix: &str, row: &Row) -> Result<Self> {
    ///         Ok(Self {
    ///             bar: MyCustomType {
    ///                 custom: row.get_value(&format!("{prefix}custom"))?
    ///             }
    ///         })
    ///     }
    /// }
    /// ```
    ///
    /// #### `try_from`
    ///
    /// When your struct contains a field whose type is not matched with the
    /// database type, if the field type has an implementation [`TryFrom`] for the
    /// database type, you can use the `try_from` attribute to convert the database
    /// type to the field type. For example:
    ///
    /// ```rust,ignore
    /// #[derive(FromRow)]
    /// struct User {
    ///     id: i32,
    ///     name: String,
    ///     #[musq(try_from = "i64")]
    ///     score: u64
    /// }
    /// ```
    pub trait FromRow<'r>: Sized {
        /// Build the type from a row, using the provided column name prefix.
        fn from_row(prefix: &str, row: &'r Row) -> Result<Self>;
    }

    /// Convert a value into a [`ValuesEntry`].
    pub trait IntoValuesEntry {
        /// Convert into a [`ValuesEntry`].
        fn into_values_entry(self) -> Result<ValuesEntry>;
    }

    /// Execute queries against a connection, pool, or transaction.
    ///
    /// This trait is sealed. The bound is nameable so callers can write generic
    /// helpers over [`Query::execute`].
    pub trait QueryExecutor: query_executor_sealed::Sealed {
        /// Execute the query and return a summary of changes.
        fn execute_query(self, query: Query) -> impl Future<Output = Result<QueryResult>> + Send;

        /// Execute the query and collect all rows.
        fn fetch_all_query(self, query: Query) -> impl Future<Output = Result<Vec<Row>>> + Send;

        /// Execute the query and fetch exactly one row.
        fn fetch_one_query(self, query: Query) -> impl Future<Output = Result<Row>> + Send;

        /// Execute the query and fetch at most one row.
        fn fetch_optional_query(
            self,
            query: Query,
        ) -> impl Future<Output = Result<Option<Row>>> + Send;

        /// Execute the query and stream rows as they are produced.
        fn fetch_query<'c>(self, query: Query) -> BoxStream<'c, Result<Row>>
        where
            Self: 'c;
    }

